// ── Helpers ────────────────────────────────────────────────
/**
 * Get all skills available to a class at or below the given level.
 */
export function getAvailableSkills(classId, level) {
    const skillIds = CLASS_SKILLS[classId] ?? [];
    return skillIds
        .map(id => SKILL_CATALOG[id])
        .filter(skill => skill.levelRequired <= level);
}
/**
 * Get the resource type used by a class.
 */
export function getClassResourceType(classId) {
    const template = CLASS_SKILLS[classId]?.[0];
    if (!template)
        return ResourceType.NONE;
    return SKILL_CATALOG[template].resourceType;
}
/** Action bar size (number of slots). */
export const ACTION_BAR_SLOTS = 8;
